Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

Add-Type -AssemblyName System.Drawing
$drawingAssembly = [System.Drawing.Bitmap].Assembly.Location
Add-Type -ReferencedAssemblies $drawingAssembly -TypeDefinition @"
using System;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;
using System.Runtime.InteropServices;

public sealed class ImageDiffResult {
    public int Width;
    public int Height;
    public long TotalPixels;
    public long ChangedPixels;
    public long PixelsOver10;
    public int MaxChannelDiff;
    public double MeanAbsoluteError;
    public double RootMeanSquareError;
}

public static class ImageDiff {
    public static ImageDiffResult Compare(string referencePath, string actualPath, string diffPath) {
        using (Bitmap referenceRaw = new Bitmap(referencePath))
        using (Bitmap actualRaw = new Bitmap(actualPath))
        using (Bitmap reference = EnsureArgb(referenceRaw))
        using (Bitmap actual = EnsureArgb(actualRaw)) {
            if (reference.Width != actual.Width || reference.Height != actual.Height) {
                throw new InvalidOperationException(
                    string.Format(
                        "Image size mismatch: reference={0}x{1}, actual={2}x{3}",
                        reference.Width,
                        reference.Height,
                        actual.Width,
                        actual.Height
                    )
                );
            }

            Rectangle rect = new Rectangle(0, 0, reference.Width, reference.Height);
            BitmapData refData = reference.LockBits(rect, ImageLockMode.ReadOnly, PixelFormat.Format32bppArgb);
            BitmapData actData = actual.LockBits(rect, ImageLockMode.ReadOnly, PixelFormat.Format32bppArgb);
            Bitmap diff = new Bitmap(reference.Width, reference.Height, PixelFormat.Format32bppArgb);
            BitmapData diffData = diff.LockBits(rect, ImageLockMode.WriteOnly, PixelFormat.Format32bppArgb);
            bool refLocked = true;
            bool actLocked = true;
            bool diffLocked = true;

            try {
                int bytes = Math.Abs(refData.Stride) * refData.Height;
                byte[] refBuffer = new byte[bytes];
                byte[] actBuffer = new byte[bytes];
                byte[] diffBuffer = new byte[bytes];
                Marshal.Copy(refData.Scan0, refBuffer, 0, bytes);
                Marshal.Copy(actData.Scan0, actBuffer, 0, bytes);

                long totalPixels = (long)reference.Width * reference.Height;
                long changedPixels = 0;
                long pixelsOver10 = 0;
                long absErrorSum = 0;
                double squaredErrorSum = 0.0;
                int maxChannelDiff = 0;

                for (int i = 0; i < bytes; i += 4) {
                    int db = Math.Abs(refBuffer[i + 0] - actBuffer[i + 0]);
                    int dg = Math.Abs(refBuffer[i + 1] - actBuffer[i + 1]);
                    int dr = Math.Abs(refBuffer[i + 2] - actBuffer[i + 2]);
                    int da = Math.Abs(refBuffer[i + 3] - actBuffer[i + 3]);
                    int maxRgb = Math.Max(dr, Math.Max(dg, db));

                    if (dr != 0 || dg != 0 || db != 0 || da != 0) {
                        changedPixels++;
                    }
                    if (maxRgb >= 10) {
                        pixelsOver10++;
                    }

                    absErrorSum += dr + dg + db;
                    squaredErrorSum += (dr * dr) + (dg * dg) + (db * db);
                    maxChannelDiff = Math.Max(maxChannelDiff, Math.Max(da, maxRgb));

                    diffBuffer[i + 0] = (byte)Math.Min(255, db * 4);
                    diffBuffer[i + 1] = (byte)Math.Min(255, dg * 4);
                    diffBuffer[i + 2] = (byte)Math.Min(255, dr * 4);
                    diffBuffer[i + 3] = 255;
                }

                Marshal.Copy(diffBuffer, 0, diffData.Scan0, bytes);
                reference.UnlockBits(refData);
                actual.UnlockBits(actData);
                diff.UnlockBits(diffData);
                refLocked = false;
                actLocked = false;
                diffLocked = false;

                string diffDir = Path.GetDirectoryName(diffPath);
                if (!string.IsNullOrEmpty(diffDir)) {
                    Directory.CreateDirectory(diffDir);
                }
                diff.Save(diffPath, ImageFormat.Png);
                diff.Dispose();

                return new ImageDiffResult {
                    Width = reference.Width,
                    Height = reference.Height,
                    TotalPixels = totalPixels,
                    ChangedPixels = changedPixels,
                    PixelsOver10 = pixelsOver10,
                    MaxChannelDiff = maxChannelDiff,
                    MeanAbsoluteError = absErrorSum / (double)(totalPixels * 3 * 255.0),
                    RootMeanSquareError = Math.Sqrt(squaredErrorSum / (double)(totalPixels * 3 * 255.0 * 255.0))
                };
            }
            catch {
                if (refLocked) reference.UnlockBits(refData);
                if (actLocked) actual.UnlockBits(actData);
                if (diffLocked) diff.UnlockBits(diffData);
                diff.Dispose();
                throw;
            }
        }
    }

    private static Bitmap EnsureArgb(Bitmap source) {
        Bitmap copy = new Bitmap(source.Width, source.Height, PixelFormat.Format32bppArgb);
        using (Graphics g = Graphics.FromImage(copy)) {
            g.DrawImage(source, 0, 0, source.Width, source.Height);
        }
        return copy;
    }
}
"@

function Resolve-ImagePath([string]$PathValue) {
    $resolved = Resolve-Path -LiteralPath $PathValue -ErrorAction Stop
    return $resolved.Path
}

$Reference = Resolve-ImagePath $Reference
$Actual = Resolve-ImagePath $Actual
if (-not $DiffOut) {
    $actualDir = Split-Path -Parent $Actual
    $actualBase = [System.IO.Path]::GetFileNameWithoutExtension($Actual)
    $DiffOut = Join-Path $actualDir "$actualBase.diff.png"
}

$result = [ImageDiff]::Compare($Reference, $Actual, $DiffOut)
$summary = [pscustomobject]@{
    reference = $Reference
    actual = $Actual
    diff = $DiffOut
    width = $result.Width
    height = $result.Height
    total_pixels = $result.TotalPixels
    changed_pixels = $result.ChangedPixels
    changed_pct = [math]::Round(($result.ChangedPixels / [double]$result.TotalPixels) * 100.0, 4)
    pixels_over_10 = $result.PixelsOver10
    pixels_over_10_pct = [math]::Round(($result.PixelsOver10 / [double]$result.TotalPixels) * 100.0, 4)
    max_channel_diff = $result.MaxChannelDiff
    mean_absolute_error = [math]::Round($result.MeanAbsoluteError, 6)
    root_mean_square_error = [math]::Round($result.RootMeanSquareError, 6)
}

if ($Json) {
    $summary | ConvertTo-Json -Depth 3
    return
}

Write-Host "Reference : $($summary.reference)"
Write-Host "Actual    : $($summary.actual)"
Write-Host "Diff image: $($summary.diff)"
Write-Host ("Size      : {0}x{1}" -f $summary.width, $summary.height)
Write-Host ("Changed   : {0} px ({1}%)" -f $summary.changed_pixels, $summary.changed_pct)
Write-Host ("Over-10   : {0} px ({1}%)" -f $summary.pixels_over_10, $summary.pixels_over_10_pct)
Write-Host ("Max diff  : {0}" -f $summary.max_channel_diff)
Write-Host ("MAE       : {0}" -f $summary.mean_absolute_error)
Write-Host ("RMSE      : {0}" -f $summary.root_mean_square_error)

use super::widget::Rect;

pub const HEADER_PAD_X: f32 = 14.0;
pub const HEADER_PAD_TOP: f32 = 12.0;
pub const HEADER_PAD_BOTTOM: f32 = 4.0;
pub const LIST_PAD_X: f32 = 6.0;
pub const LIST_PAD_Y: f32 = 4.0;
pub const ITEM_PAD_X: f32 = 8.0;
pub const ITEM_PAD_Y: f32 = 7.0;
pub const ITEM_MARGIN_BOTTOM: f32 = 2.0;
pub const ROW_GAP_X: f32 = 8.0;
pub const SECONDARY_PAD_LEFT: f32 = 20.0;
pub const SECONDARY_MARGIN_TOP: f32 = 2.0;
pub const SESSION_NUMBER_MIN_WIDTH: f32 = 10.0;
pub const ACTIVE_BORDER_W: f32 = 3.0;
pub const HEADER_LABEL_FONT_PX: f32 = 12.0;
pub const HEADER_LIGHTNING_FONT_PX: f32 = 10.0;
pub const SESSION_NUMBER_FONT_PX: f32 = 12.0;
pub const SESSION_NAME_FONT_PX: f32 = 13.0;
pub const SESSION_SECONDARY_FONT_PX: f32 = 11.0;

#[derive(Debug, Clone, Copy)]
pub struct SessionStackItemSpec {
    pub has_secondary: bool,
}

#[derive(Debug, Clone)]
pub struct SidebarSessionItemLayout {
    pub outer: Rect,
    pub first_row: Rect,
    pub secondary_row: Option<Rect>,
}

#[derive(Debug, Clone)]
pub struct SidebarSessionLayout {
    pub header: Rect,
    pub header_content: Rect,
    pub list: Rect,
    pub items: Vec<SidebarSessionItemLayout>,
}

impl SidebarSessionLayout {
    pub fn item_rect(&self, index: usize) -> Option<Rect> {
        self.items.get(index).map(|item| item.outer)
    }

    pub fn items_bottom(&self) -> f32 {
        self.items
            .last()
            .map(|item| item.outer.bottom())
            .unwrap_or(self.list.y)
    }
}

pub fn compute_sidebar_session_layout(
    sidebar: Rect,
    scale: f32,
    items: &[SessionStackItemSpec],
) -> SidebarSessionLayout {
    let s = |value: f32| (value * scale).round();

    let header_content_h = s(HEADER_LABEL_FONT_PX.max(HEADER_LIGHTNING_FONT_PX));
    let header_h = s(HEADER_PAD_TOP) + header_content_h + s(HEADER_PAD_BOTTOM);
    let header = Rect {
        x: sidebar.x,
        y: sidebar.y,
        width: sidebar.width,
        height: header_h,
    };
    let header_content = Rect {
        x: sidebar.x + s(HEADER_PAD_X),
        y: sidebar.y + s(HEADER_PAD_TOP),
        width: (sidebar.width - s(HEADER_PAD_X * 2.0)).max(0.0),
        height: header_content_h,
    };
    let list = Rect {
        x: sidebar.x + s(LIST_PAD_X),
        y: header.bottom() + s(LIST_PAD_Y),
        width: (sidebar.width - s(LIST_PAD_X * 2.0)).max(0.0),
        height: (sidebar.height - header_h - s(LIST_PAD_Y * 2.0)).max(0.0),
    };

    let first_row_h = s(SESSION_NAME_FONT_PX.max(SESSION_NUMBER_FONT_PX.max(SESSION_SECONDARY_FONT_PX)));
    let secondary_row_h = s(SESSION_SECONDARY_FONT_PX);
    let mut item_y = list.y;
    let item_w = list.width;
    let mut item_layouts = Vec::with_capacity(items.len());

    for item in items {
        let item_h = s(ITEM_PAD_Y * 2.0)
            + first_row_h
            + if item.has_secondary {
                s(SECONDARY_MARGIN_TOP) + secondary_row_h
            } else {
                0.0
            };
        let outer = Rect {
            x: list.x,
            y: item_y,
            width: item_w,
            height: item_h,
        };
        let first_row = Rect {
            x: outer.x + s(ITEM_PAD_X),
            y: outer.y + s(ITEM_PAD_Y),
            width: (outer.width - s(ITEM_PAD_X * 2.0)).max(0.0),
            height: first_row_h,
        };
        let secondary_row = item.has_secondary.then(|| Rect {
            x: outer.x + s(ITEM_PAD_X + SECONDARY_PAD_LEFT),
            y: first_row.bottom() + s(SECONDARY_MARGIN_TOP),
            width: (outer.width - s(ITEM_PAD_X * 2.0 + SECONDARY_PAD_LEFT)).max(0.0),
            height: secondary_row_h,
        });
        item_layouts.push(SidebarSessionItemLayout {
            outer,
            first_row,
            secondary_row,
        });
        item_y = outer.bottom() + s(ITEM_MARGIN_BOTTOM);
    }

    SidebarSessionLayout {
        header,
        header_content,
        list,
        items: item_layouts,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn session_stack_matches_web_spacing() {
        let layout = compute_sidebar_session_layout(
            Rect {
                x: 0.0,
                y: 36.0,
                width: 200.0,
                height: 400.0,
            },
            1.0,
            &[
                SessionStackItemSpec {
                    has_secondary: true,
                },
                SessionStackItemSpec {
                    has_secondary: true,
                },
                SessionStackItemSpec {
                    has_secondary: true,
                },
            ],
        );

        assert_eq!(layout.header.height, 28.0);
        assert_eq!(layout.header_content.x, 14.0);
        assert_eq!(layout.header_content.y, 48.0);
        assert_eq!(layout.items[0].outer.x, 6.0);
        assert_eq!(layout.items[0].outer.y, 68.0);
        assert_eq!(layout.items[0].outer.width, 188.0);
        assert_eq!(layout.items[0].outer.height, 40.0);
        assert_eq!(layout.items[1].outer.y, 110.0);
        assert_eq!(layout.items[0].first_row.y, 75.0);
        assert_eq!(
            layout.items[0].secondary_row.expect("secondary row").x,
            34.0
        );
        assert_eq!(
            layout.items[0].secondary_row.expect("secondary row").y,
            90.0
        );
    }

    #[test]
    fn compact_item_hides_secondary_row() {
        let layout = compute_sidebar_session_layout(
            Rect {
                x: 0.0,
                y: 0.0,
                width: 200.0,
                height: 200.0,
            },
            1.0,
            &[SessionStackItemSpec {
                has_secondary: false,
            }],
        );

        assert_eq!(layout.items[0].outer.height, 27.0);
        assert!(layout.items[0].secondary_row.is_none());
    }
}

//! Deterministic cropped web-reference transcript for visual parity captures.
//!
//! This scene intentionally matches the visible composition of
//! `docs/references/web-reference.png`, which is a top-left crop of the fuller
//! JSX prototype rather than the entire shell viewport.

use std::cell::RefCell;

use super::builder::{colors, font_scale, UiBuilder, UiTextRenderer};
use super::reference_layout::{
    ReferencePaneLayoutEngine, BLOCK_COMMAND, BLOCK_CURSOR, BLOCK_EDITING, BLOCK_INTRO,
    BLOCK_PARAGRAPH_COLLAPSE, BLOCK_PARAGRAPH_TONE, BLOCK_RESIDUAL_HEADING,
    BLOCK_RESIDUAL_NUMBERED, BLOCK_RESIDUAL_PARAGRAPH, BLOCK_SMOKE_BULLET, BLOCK_THOUGHTS_ONE,
    BLOCK_THOUGHTS_TWO, BLOCK_USER_COMPACT, BLOCK_USER_FUN, BLOCK_VERIFICATION_BULLET,
    BLOCK_VERIFICATION_HEADING,
};
use super::widget::Rect;

const BODY_SCALE: f32 = font_scale::PX13;
const SMALL_SCALE: f32 = font_scale::PX12;
const HEADING_SCALE: f32 = 1.0;
const LINK_COLOR: [f32; 4] = colors::ACCENT_SKY;
const CODE_BG: [f32; 4] = [0.110, 0.125, 0.188, 1.0]; // #1c2030
const BODY_LINE_HEIGHT: f32 = 13.0 * 1.55;
const PARAGRAPH_LINE_HEIGHT: f32 = 13.0 * 1.6;
const INLINE_GAP: f32 = 8.0;
const THOUGHTS_GAP: f32 = 6.0;
const SUB_BULLET_INDENT: f32 = 12.0;

pub struct ReferencePane {
    layout_engine: RefCell<ReferencePaneLayoutEngine>,
}

impl ReferencePane {
    pub fn new() -> Self {
        Self {
            layout_engine: RefCell::new(ReferencePaneLayoutEngine::new()),
        }
    }

    pub fn build(&self, ui: &mut UiBuilder, pane: Rect, text: &UiTextRenderer) {
        let bg = colors::BG_BASE;
        let s = |v: f32| text.s(v);
        let layout = self.layout_engine.borrow_mut().compute(pane, text);
        let body_x = layout.content.x;
        let bullet_text_x = body_x + self.inline_lead(text, "\u{2022}", BODY_SCALE, INLINE_GAP);

        self.draw_bullet_text(
            ui,
            text,
            layout.blocks[BLOCK_INTRO].x,
            layout.blocks[BLOCK_INTRO].y,
            "Tightened the support story so the README stays clearly tmux-first while still acknowledging the experimental zellij code in-repo.",
            bg,
        );

        self.draw_heading(
            ui,
            text,
            layout.blocks[BLOCK_VERIFICATION_HEADING].x,
            layout.blocks[BLOCK_VERIFICATION_HEADING].y,
            "Verification Notes",
            bg,
        );

        self.draw_bullet_runs(
            ui,
            text,
            layout.blocks[BLOCK_VERIFICATION_BULLET].x,
            layout.blocks[BLOCK_VERIFICATION_BULLET].y,
            &[
                InlineRun::Text("The rewritten "),
                InlineRun::Link("README.md"),
                InlineRun::Text(" now reflects the actual sidebar surface:"),
            ],
            bg,
        );
        self.draw_sub_bullets(
            ui,
            text,
            bullet_text_x + s(SUB_BULLET_INDENT),
            layout.blocks[BLOCK_VERIFICATION_BULLET].y + s(BODY_LINE_HEIGHT) + s(2.0),
            &[
                "session list shows branch and agent status",
                "detail panel shows working directory, ports, agent rows, and thread names",
                "users can hide/restore/kill/reorder sessions and switch themes",
                "detected localhost ports open from the UI",
            ],
            bg,
        );

        self.draw_bullet_runs(
            ui,
            text,
            layout.blocks[BLOCK_SMOKE_BULLET].x,
            layout.blocks[BLOCK_SMOKE_BULLET].y,
            &[
                InlineRun::Text("I also verified the smoke-test path directly: "),
                InlineRun::Code("bun test"),
                InlineRun::Text(" from the repo root passes right now with 167 passing tests."),
            ],
            bg,
        );

        self.draw_heading(
            ui,
            text,
            layout.blocks[BLOCK_RESIDUAL_HEADING].x,
            layout.blocks[BLOCK_RESIDUAL_HEADING].y,
            "One Residual Note",
            bg,
        );

        self.draw_paragraph(
            ui,
            text,
            layout.blocks[BLOCK_RESIDUAL_PARAGRAPH].x,
            layout.blocks[BLOCK_RESIDUAL_PARAGRAPH].y,
            "I only changed the README. While auditing, I noticed some secondary docs still have minor drift from the current UI behavior, especially the feature/keybinding docs.",
            bg,
        );

        self.draw_numbered_runs(
            ui,
            text,
            layout.blocks[BLOCK_RESIDUAL_NUMBERED].x,
            layout.blocks[BLOCK_RESIDUAL_NUMBERED].y,
            &[
                InlineRun::Text("If you want, I can do the same line-by-line cleanup pass on "),
                InlineRun::Link("docs/reference/features-and-keybindings.md"),
                InlineRun::Text(" and the rest of "),
                InlineRun::Code("docs/"),
                InlineRun::Text(" next."),
            ],
            bg,
        );

        self.draw_user_message(
            ui,
            text,
            layout.blocks[BLOCK_USER_FUN].x,
            layout.blocks[BLOCK_USER_FUN].y,
            "also make it a bit more fun! (interrupted)",
            bg,
        );
        self.draw_user_message(
            ui,
            text,
            layout.blocks[BLOCK_USER_COMPACT].x,
            layout.blocks[BLOCK_USER_COMPACT].y,
            "and compact!",
            bg,
        );

        self.draw_thoughts_row(
            ui,
            text,
            layout.blocks[BLOCK_THOUGHTS_ONE].x,
            layout.blocks[BLOCK_THOUGHTS_ONE].y,
            2,
            bg,
        );
        self.draw_paragraph(
            ui,
            text,
            layout.blocks[BLOCK_PARAGRAPH_TONE].x,
            layout.blocks[BLOCK_PARAGRAPH_TONE].y,
            "I'm tightening the README again, this time for tone and density: shorter sections, less repetition, and a little more personality without getting cute enough to obscure what the project does.",
            bg,
        );

        self.draw_command_row(
            ui,
            text,
            layout.blocks[BLOCK_COMMAND].x,
            layout.blocks[BLOCK_COMMAND].y,
            layout.blocks[BLOCK_COMMAND].width,
            "$ rtk proxy nl -ba README.md | sed -n '1,220p'",
            bg,
        );

        self.draw_thoughts_row(
            ui,
            text,
            layout.blocks[BLOCK_THOUGHTS_TWO].x,
            layout.blocks[BLOCK_THOUGHTS_TWO].y,
            2,
            bg,
        );
        self.draw_paragraph(
            ui,
            text,
            layout.blocks[BLOCK_PARAGRAPH_COLLAPSE].x,
            layout.blocks[BLOCK_PARAGRAPH_COLLAPSE].y,
            "I'm collapsing the README structure now: fewer headings, less \"verification report\" tone, and more \"here's why this is useful\" energy. The goal is that the first screen reads fast and still feels grounded in the actual code.",
            bg,
        );

        self.draw_editing_row(
            ui,
            text,
            layout.blocks[BLOCK_EDITING].x,
            layout.blocks[BLOCK_EDITING].y,
            bg,
        );
        self.draw_cursor(
            ui,
            text,
            layout.blocks[BLOCK_CURSOR].x,
            layout.blocks[BLOCK_CURSOR].y,
        );
    }

    fn draw_heading(
        &self,
        ui: &mut UiBuilder,
        text: &UiTextRenderer,
        x: f32,
        y: f32,
        label: &str,
        bg: [f32; 4],
    ) -> f32 {
        ui.text_mono_bold_scaled_mixed(text, label, x, y, colors::FG_BRIGHT, bg, HEADING_SCALE);
        y + text.s(14.0)
    }

    fn draw_paragraph(
        &self,
        ui: &mut UiBuilder,
        text: &UiTextRenderer,
        x: f32,
        y: f32,
        label: &str,
        bg: [f32; 4],
    ) -> f32 {
        ui.text_mono_scaled_mixed(text, label, x, y, colors::FG_PRIMARY, bg, BODY_SCALE);
        y + text.s(PARAGRAPH_LINE_HEIGHT)
    }

    fn draw_bullet_text(
        &self,
        ui: &mut UiBuilder,
        text: &UiTextRenderer,
        x: f32,
        y: f32,
        label: &str,
        bg: [f32; 4],
    ) -> f32 {
        ui.text_mono_scaled_mixed(text, "\u{2022}", x, y, colors::FG_MUTED, bg, BODY_SCALE);
        ui.text_mono_scaled_mixed(
            text,
            label,
            x + self.inline_lead(text, "\u{2022}", BODY_SCALE, INLINE_GAP),
            y,
            colors::FG_PRIMARY,
            bg,
            BODY_SCALE,
        );
        y + text.s(BODY_LINE_HEIGHT)
    }

    fn draw_bullet_runs(
        &self,
        ui: &mut UiBuilder,
        text: &UiTextRenderer,
        x: f32,
        y: f32,
        runs: &[InlineRun<'_>],
        bg: [f32; 4],
    ) -> f32 {
        ui.text_mono_scaled_mixed(text, "\u{2022}", x, y, colors::FG_MUTED, bg, BODY_SCALE);
        self.draw_inline_runs(
            ui,
            text,
            x + self.inline_lead(text, "\u{2022}", BODY_SCALE, INLINE_GAP),
            y,
            runs,
            BODY_SCALE,
            bg,
        );
        y + text.s(BODY_LINE_HEIGHT)
    }

    fn draw_sub_bullets(
        &self,
        ui: &mut UiBuilder,
        text: &UiTextRenderer,
        x: f32,
        mut y: f32,
        lines: &[&str],
        bg: [f32; 4],
    ) -> f32 {
        for line in lines {
            ui.text_mono_scaled_mixed(
                text,
                "\u{2022}",
                x,
                y,
                colors::STATUS_DEFAULT,
                bg,
                SMALL_SCALE,
            );
            ui.text_mono_scaled_mixed(
                text,
                line,
                x + self.inline_lead(text, "\u{2022}", SMALL_SCALE, INLINE_GAP),
                y,
                colors::FG_SECONDARY,
                bg,
                SMALL_SCALE,
            );
            y += text.s(14.0);
        }
        y
    }

    fn draw_numbered_runs(
        &self,
        ui: &mut UiBuilder,
        text: &UiTextRenderer,
        x: f32,
        y: f32,
        runs: &[InlineRun<'_>],
        bg: [f32; 4],
    ) -> f32 {
        ui.text_mono_scaled_mixed(text, "1.", x, y, colors::FG_MUTED, bg, BODY_SCALE);
        self.draw_inline_runs(
            ui,
            text,
            x + self.inline_lead(text, "1.", BODY_SCALE, INLINE_GAP),
            y,
            runs,
            BODY_SCALE,
            bg,
        );
        y + text.s(BODY_LINE_HEIGHT)
    }

    fn draw_user_message(
        &self,
        ui: &mut UiBuilder,
        text: &UiTextRenderer,
        x: f32,
        y: f32,
        label: &str,
        bg: [f32; 4],
    ) -> f32 {
        let s = |v: f32| text.s(v);
        let text_h = s(13.0);
        let rect = Rect {
            x,
            y,
            width: text.text_width_mono_scaled(label, BODY_SCALE) + s(24.0),
            height: text_h + s(12.0),
        };
        ui.fill_rounded(
            Rect {
                x: rect.x + s(3.0),
                y: rect.y,
                width: rect.width - s(3.0),
                height: rect.height,
            },
            colors::BG_ACTIVE_ACC,
            s(4.0),
        );
        ui.fill(
            Rect {
                x: rect.x,
                y: rect.y,
                width: s(3.0),
                height: rect.height,
            },
            colors::ACCENT_BLUE,
        );
        ui.text_mono_scaled_mixed(
            text,
            label,
            rect.x + s(12.0),
            rect.y + s(6.0),
            [0.769, 0.698, 0.541, 1.0], // #c4b28a
            bg,
            BODY_SCALE,
        );
        rect.bottom()
    }

    fn draw_thoughts_row(
        &self,
        ui: &mut UiBuilder,
        text: &UiTextRenderer,
        x: f32,
        y: f32,
        count: u32,
        bg: [f32; 4],
    ) -> f32 {
        let label = format!("{count} thoughts >");
        ui.text_mono_scaled_mixed(
            text,
            "\u{2713}",
            x,
            y,
            colors::ACCENT_GREEN,
            bg,
            SMALL_SCALE,
        );
        ui.text_mono_scaled_mixed(
            text,
            &label,
            x + self.inline_lead(text, "\u{2713}", SMALL_SCALE, THOUGHTS_GAP),
            y,
            colors::FG_MUTED,
            bg,
            SMALL_SCALE,
        );
        y + text.s(13.0)
    }

    fn draw_command_row(
        &self,
        ui: &mut UiBuilder,
        text: &UiTextRenderer,
        x: f32,
        y: f32,
        width: f32,
        command: &str,
        bg: [f32; 4],
    ) -> f32 {
        let s = |v: f32| text.s(v);
        let rect = Rect {
            x,
            y,
            width,
            height: s(24.0),
        };
        ui.fill_rounded(rect, [0.039, 0.047, 0.063, 1.0], s(5.0)); // #0a0c10
        ui.stroke_rounded(rect, s(5.0), 1.0, [0.118, 0.129, 0.157, 1.0]); // #1e2128
        ui.text_mono_scaled_mixed(
            text,
            command,
            rect.x + s(10.0),
            rect.y + s(6.0),
            colors::FG_SECONDARY,
            bg,
            SMALL_SCALE,
        );
        let arrow = "\u{25B8}";
        let arrow_w = text.text_width_mono_scaled(arrow, SMALL_SCALE);
        ui.text_mono_scaled_mixed(
            text,
            arrow,
            rect.right() - arrow_w - s(10.0),
            rect.y + s(6.0),
            colors::STATUS_PATH,
            bg,
            SMALL_SCALE,
        );
        rect.bottom()
    }

    fn draw_editing_row(
        &self,
        ui: &mut UiBuilder,
        text: &UiTextRenderer,
        x: f32,
        y: f32,
        bg: [f32; 4],
    ) -> f32 {
        ui.text_mono_scaled_mixed(text, "::", x, y, colors::STATUS_PATH, bg, SMALL_SCALE);
        let lead = self.inline_lead(text, "::", SMALL_SCALE, THOUGHTS_GAP);
        ui.text_mono_scaled_mixed(
            text,
            "Editing files",
            x + lead,
            y,
            colors::FG_MUTED,
            bg,
            SMALL_SCALE,
        );
        ui.text_mono_scaled_mixed(
            text,
            "\u{25B8}",
            x + lead
                + text.text_width_mono_scaled("Editing files", SMALL_SCALE)
                + text.s(THOUGHTS_GAP),
            y,
            colors::STATUS_PATH,
            bg,
            SMALL_SCALE,
        );
        y + text.s(12.0)
    }

    fn draw_cursor(&self, ui: &mut UiBuilder, text: &UiTextRenderer, x: f32, y: f32) {
        ui.fill_rounded(
            Rect {
                x,
                y,
                width: text.s(8.0),
                height: text.s(16.0),
            },
            colors::ACCENT_BLUE,
            text.s(1.0),
        );
    }

    fn draw_inline_runs(
        &self,
        ui: &mut UiBuilder,
        text: &UiTextRenderer,
        mut x: f32,
        y: f32,
        runs: &[InlineRun<'_>],
        scale: f32,
        bg: [f32; 4],
    ) {
        let s = |v: f32| text.s(v);
        for run in runs {
            match run {
                InlineRun::Text(value) => {
                    ui.text_mono_scaled_mixed(text, value, x, y, colors::FG_PRIMARY, bg, scale);
                    x += text.text_width_mono_scaled(value, scale);
                }
                InlineRun::Link(value) => {
                    ui.text_mono_scaled_mixed(text, value, x, y, LINK_COLOR, bg, scale);
                    let width = text.text_width_mono_scaled(value, scale);
                    ui.hline_aa(
                        x,
                        y + text.cell_height * scale + s(1.0),
                        width,
                        1.0,
                        LINK_COLOR,
                    );
                    x += width;
                }
                InlineRun::Code(value) => {
                    let code_scale = SMALL_SCALE;
                    let pad_x = s(5.0);
                    let code_w = text.text_width_mono_scaled(value, code_scale);
                    let code_h = s(16.0);
                    let rect = Rect {
                        x,
                        y: y + s(1.0),
                        width: code_w + pad_x * 2.0,
                        height: code_h,
                    };
                    ui.fill_rounded(rect, CODE_BG, s(3.0));
                    ui.text_mono_scaled_mixed(
                        text,
                        value,
                        rect.x + pad_x,
                        rect.y + s(1.0),
                        colors::ACCENT_GOLD,
                        CODE_BG,
                        code_scale,
                    );
                    x += rect.width;
                }
            }
        }
    }

    fn inline_lead(&self, text: &UiTextRenderer, marker: &str, scale: f32, gap: f32) -> f32 {
        text.text_width_mono_scaled(marker, scale) + text.s(gap)
    }
}

enum InlineRun<'a> {
    Text(&'a str),
    Link(&'a str),
    Code(&'a str),
}

use std::cell::RefCell;
use std::collections::HashMap;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum UiFontKind {
    Sans,
    Serif,
    Mono,
}

#[derive(Debug, Clone)]
pub struct UiTextLayout {
    pub width: f32,
    pub line_height: f32,
    pub glyph_offsets: Vec<f32>,
}

#[derive(Debug, Clone)]
pub struct UiFontFamilies {
    pub sans: String,
    pub serif: String,
    pub mono: String,
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
struct LayoutKey {
    font: UiFontKind,
    text: String,
    size_q4: u16,
    bold: bool,
    italic: bool,
}

#[cfg(windows)]
struct LayoutCache {
    factory: windows::Win32::Graphics::DirectWrite::IDWriteFactory,
    families: UiFontFamilies,
    cache: HashMap<LayoutKey, UiTextLayout>,
}

pub struct UiTextLayoutEngine {
    #[cfg(windows)]
    inner: RefCell<LayoutCache>,
}

impl UiTextLayoutEngine {
    #[cfg(windows)]
    pub fn new(families: UiFontFamilies) -> windows::core::Result<Self> {
        use windows::Win32::Graphics::DirectWrite::{
            DWriteCreateFactory, IDWriteFactory, DWRITE_FACTORY_TYPE_SHARED,
        };

        let factory: IDWriteFactory = unsafe { DWriteCreateFactory(DWRITE_FACTORY_TYPE_SHARED)? };
        Ok(Self {
            inner: RefCell::new(LayoutCache {
                factory,
                families,
                cache: HashMap::new(),
            }),
        })
    }

    #[cfg(not(windows))]
    pub fn new(_families: UiFontFamilies) -> Result<Self, ()> {
        Ok(Self {})
    }

    pub fn layout(
        &self,
        font: UiFontKind,
        text: &str,
        font_size_px: f32,
        bold: bool,
        italic: bool,
    ) -> Option<UiTextLayout> {
        #[cfg(windows)]
        {
            let key = LayoutKey {
                font,
                text: text.to_string(),
                size_q4: (font_size_px.max(0.0) * 4.0).round() as u16,
                bold,
                italic,
            };
            let mut inner = self.inner.borrow_mut();
            if let Some(layout) = inner.cache.get(&key) {
                return Some(layout.clone());
            }
            let layout = compute_layout(&inner.factory, &inner.families, &key)?;
            inner.cache.insert(key, layout.clone());
            Some(layout)
        }
        #[cfg(not(windows))]
        {
            let _ = (font, text, font_size_px, bold, italic);
            None
        }
    }
}

#[cfg(windows)]
fn compute_layout(
    factory: &windows::Win32::Graphics::DirectWrite::IDWriteFactory,
    families: &UiFontFamilies,
    key: &LayoutKey,
) -> Option<UiTextLayout> {
    use windows::core::PCWSTR;
    use windows::Win32::Graphics::DirectWrite::{
        DWRITE_FONT_STRETCH_NORMAL, DWRITE_FONT_STYLE_ITALIC, DWRITE_FONT_STYLE_NORMAL,
        DWRITE_FONT_WEIGHT_BOLD, DWRITE_FONT_WEIGHT_REGULAR, DWRITE_HIT_TEST_METRICS,
        DWRITE_TEXT_METRICS, DWRITE_WORD_WRAPPING_NO_WRAP,
    };

    let family = match key.font {
        UiFontKind::Sans => &families.sans,
        UiFontKind::Serif => &families.serif,
        UiFontKind::Mono => &families.mono,
    };
    let family_wide = wide(family);
    let locale = wide("en-US");
    let utf16: Vec<u16> = key.text.encode_utf16().collect();

    let weight = if key.bold {
        DWRITE_FONT_WEIGHT_BOLD
    } else {
        DWRITE_FONT_WEIGHT_REGULAR
    };
    let style = if key.italic {
        DWRITE_FONT_STYLE_ITALIC
    } else {
        DWRITE_FONT_STYLE_NORMAL
    };
    let font_size_px = key.size_q4 as f32 / 4.0;

    let format = unsafe {
        factory
            .CreateTextFormat(
                PCWSTR(family_wide.as_ptr()),
                None,
                weight,
                style,
                DWRITE_FONT_STRETCH_NORMAL,
                font_size_px,
                PCWSTR(locale.as_ptr()),
            )
            .ok()?
    };
    let _ = unsafe { format.SetWordWrapping(DWRITE_WORD_WRAPPING_NO_WRAP) };

    let layout = unsafe {
        factory
            .CreateTextLayout(&utf16, &format, 4096.0, 4096.0)
            .ok()?
    };

    let mut metrics = DWRITE_TEXT_METRICS::default();
    unsafe { layout.GetMetrics(&mut metrics).ok()? };

    let mut glyph_offsets = Vec::with_capacity(key.text.chars().count());
    let mut utf16_index = 0u32;
    for ch in key.text.chars() {
        let mut x = 0.0f32;
        let mut y = 0.0f32;
        let mut hit = DWRITE_HIT_TEST_METRICS::default();
        unsafe {
            layout
                .HitTestTextPosition(utf16_index, false, &mut x, &mut y, &mut hit)
                .ok()?;
        }
        glyph_offsets.push(x);
        utf16_index += ch.len_utf16() as u32;
    }

    Some(UiTextLayout {
        width: metrics.widthIncludingTrailingWhitespace.max(metrics.width),
        line_height: metrics.height.max(font_size_px),
        glyph_offsets,
    })
}

#[cfg(windows)]
fn wide(value: &str) -> Vec<u16> {
    value.encode_utf16().chain(std::iter::once(0)).collect()
}

