function StatusDot({ color, size = 7 }) {
  return (
    <span
      style={{
        width: size,
        height: size,
        borderRadius: "50%",
        backgroundColor: color,
        display: "inline-block",
        flexShrink: 0,
      }}
    />
  );
}

function Badge({ count, color }) {
  if (!count) return null;
  return (
    <span
      style={{
        backgroundColor: color,
        color: "#fff",
        fontSize: 9,
        fontWeight: 700,
        borderRadius: 7,
        padding: "1px 5px",
        minWidth: 16,
        height: 16,
        display: "inline-flex",
        alignItems: "center",
        justifyContent: "center",
        lineHeight: 1,
      }}
    >
      {count}
    </span>
  );
}

function ThoughtsBlock({ count, items, defaultOpen = false }) {
  const [open, setOpen] = useState(defaultOpen);
  return (
    <div style={{ margin: "8px 0 6px" }}>
      <div
        onClick={() => setOpen(!open)}
        style={{
          display: "flex",
          alignItems: "center",
          gap: 6,
          cursor: "pointer",
          color: "#6e7681",
          fontSize: 12,
          userSelect: "none",
        }}
      >
        <span style={{ color: "#22c55e", fontSize: 13 }}>Ô£ô</span>
        <span>{count} thoughts {open ? "Ôû¥" : "Ôû©"}</span>
      </div>
      {open && (
        <div style={{ paddingLeft: 20, marginTop: 4 }}>
          {items.map((item, i) => (
            <div
              key={i}
              style={{
                display: "flex",
                alignItems: "center",
                gap: 6,
                color: "#484f58",
                fontSize: 12,
                padding: "1px 0",
              }}
            >
              <span style={{ color: "#3b4048" }}>┬À</span>
              <span>{item}</span>
              <span style={{ color: "#3b4048", marginLeft: 2 }}>Ôû©</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function InlineContent({ children }) {
  if (!children) return null;
  return (
    <span>
      {children.map((c, i) => {
        if (c.link) {
          return (
            <span key={i} style={{ color: "#58a6ff", textDecoration: "underline", cursor: "pointer" }}>
              {c.text}
            </span>
          );
        }
        if (c.code) {
          return (
            <span
              key={i}
              style={{
                backgroundColor: "#1c2030",
                color: "#e6a855",
                padding: "1px 5px",
                borderRadius: 3,
                fontSize: 12,
                fontFamily: "inherit",
              }}
            >
              {c.text}
            </span>
          );
        }
        return <span key={i}>{c.text}</span>;
      })}
    </span>
  );
}

function RichBlock({ block }) {
  if (block.type === "heading") {
    return (
      <h3
        style={{
          color: "#e6edf3",
          fontSize: 14,
          fontWeight: 700,
          margin: "18px 0 8px",
          fontFamily: "inherit",
          letterSpacing: 0.2,
        }}
      >
        {block.text}
      </h3>
    );
  }

  if (block.type === "bullet") {
    return (
      <div style={{ display: "flex", gap: 8, margin: "4px 0", lineHeight: 1.55, fontSize: 13 }}>
        <span style={{ color: "#6e7681", flexShrink: 0 }}>ÔÇó</span>
        <div>
          {block.children ? <InlineContent children={block.children} /> : <span>{block.text}</span>}
          {block.sub && (
            <div style={{ paddingLeft: 12, marginTop: 2 }}>
              {block.sub.map((s, i) => (
                <div key={i} style={{ display: "flex", gap: 8, color: "#8b949e", fontSize: 12, padding: "1px 0" }}>
                  <span style={{ color: "#484f58" }}>ÔÇó</span>
                  <span>{s}</span>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    );
  }

  if (block.type === "numbered") {
    return (
      <div style={{ display: "flex", gap: 8, margin: "4px 0", lineHeight: 1.55, fontSize: 13 }}>
        <span style={{ color: "#6e7681", flexShrink: 0 }}>1.</span>
        <span>
          <InlineContent children={block.children} />
        </span>
      </div>
    );
  }

  if (block.type === "paragraph") {
    return (
      <p style={{ margin: "8px 0", lineHeight: 1.6, fontSize: 13, color: "#c9d1d9" }}>{block.text}</p>
    );
  }

  if (block.type === "user-message") {
    return (
      <div
        style={{
          borderLeft: "3px solid #6366f1",
          backgroundColor: "#14171f",
          padding: "6px 12px",
          margin: "6px 0",
          borderRadius: "0 4px 4px 0",
          color: block.highlight || "#c9d1d9",
          fontSize: 13,
          fontWeight: 500,
        }}
      >
        {block.text}
      </div>
    );
  }

  if (block.type === "thoughts") {
    return <ThoughtsBlock count={block.count} items={block.items} />;
  }

  if (block.type === "command") {
    return (
      <div
        style={{
          backgroundColor: "#0a0c10",
          border: "1px solid #1e2128",
          borderRadius: 5,
          padding: "6px 10px",
          margin: "8px 0",
          fontSize: 12,
          color: "#8b949e",
          display: "flex",
          alignItems: "center",
          gap: 6,
        }}
      >
        <span style={{ color: "#6e7681", fontFamily: "inherit" }}>{block.text}</span>
        <span style={{ color: "#3b4048", marginLeft: "auto" }}>Ôû©</span>
      </div>
    );
  }

  if (block.type === "editing") {
    return (
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 6,
          color: "#6e7681",
          fontSize: 12,
          margin: "6px 0",
        }}
      >
        <span style={{ color: "#3b4048" }}>::</span>
        <span>{block.text}</span>
        <span style={{ color: "#3b4048" }}>Ôû©</span>
      </div>
    );
  }

  return null;
}

function ProgressBar() {
  const [width, setWidth] = useState(5);
  useEffect(() => {
    const timer = setInterval(() => {
      setWidth((w) => (w >= 90 ? 5 : w + Math.random() * 2));
    }, 300);
    return () => clearInterval(timer);
  }, []);
  return (
    <div style={{ height: 2, backgroundColor: "#1e2128", width: "100%", overflow: "hidden" }}>
      <div
        style={{
          height: "100%",
          width: `${width}%`,
          background: "linear-gradient(90deg, #6366f1, #8b5cf6, #6366f1)",
          transition: "width 0.3s ease",
          borderRadius: 1,
        }}
      />
    </div>
  );
}

/* ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ SCROLLBAR STYLES ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */
const scrollCSS = `
  * { box-sizing: border-box; }
  ::-webkit-scrollbar { width: 6px; height: 6px; }
  ::-webkit-scrollbar-track { background: transparent; }
  ::-webkit-scrollbar-thumb { background: #2d333b; border-radius: 3px; }
  ::-webkit-scrollbar-thumb:hover { background: #3b4048; }
  @keyframes blink { 0%,100%{opacity:1} 50%{opacity:0} }
  @keyframes pulse { 0%,100%{opacity:0.6} 50%{opacity:1} }
  @keyframes spin { 0%{transform:rotate(0deg)} 100%{transform:rotate(360deg)} }
`;

/* ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ MAIN COMPONENT ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */

export default function GodlyTerminal() {
  const [activeTab, setActiveTab] = useState(2);
  const [activeSession, setActiveSession] = useState(2);
  const [sidebarWidth, setSidebarWidth] = useState(200);
