            <span style={{ fontSize: 13 }}>­ƒƒá</span>
            <span style={{ fontWeight: 600 }}>bun</span>
          </span>
          <span style={{ display: "flex", alignItems: "center", gap: 4 }}>
            <span style={{ width: 8, height: 8, borderRadius: "50%", backgroundColor: "#22c55e", display: "inline-block" }} />
